import"./MainLayout.astro_astro_type_script_index_0_lang.Cr6jjJfi.js";const n=document.getElementById("login-form"),t=document.getElementById("error-msg"),s=document.getElementById("error-text"),a=document.getElementById("btn-label"),r=document.getElementById("btn-loading");localStorage.getItem("gab_token")&&(location.href="/home");n.addEventListener("submit",async d=>{d.preventDefault(),t.classList.add("hidden"),a.classList.add("hidden"),r.classList.remove("hidden");const i=Object.fromEntries(new FormData(n));try{const o=await fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(i)}),e=await o.json();if(!o.ok){s.textContent=e.error||"Erro ao entrar.",t.classList.remove("hidden");return}localStorage.setItem("gab_token",e.token),localStorage.setItem("gab_user",JSON.stringify(e.user)),location.href="/home"}catch{s.textContent="Sem conexão com o servidor.",t.classList.remove("hidden")}finally{a.classList.remove("hidden"),r.classList.add("hidden")}});
